const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const colors={물:'#79c4db',불:'#ed9b66',흙:'#c8b17b',바람:'#b7dbac',나무:'#80c69c',쇠:'#d9e1db',번개:'#c3a8ff'};
const weaponPaths={검:'M8 55 L52 9 L58 5 L54 13 L16 59 M6 48 L24 64 M9 61 L4 66',도:'M10 57 Q28 20 59 9 Q49 38 16 61 M7 51 L23 63',창:'M6 66 L52 14 M46 14 L63 2 L59 23 Z',활:'M17 6 Q62 34 17 64 M17 6 L17 64 M4 35 L64 35 M56 29 L64 35 L56 41',지팡이:'M16 63 L46 15 M41 15 A10 10 0 1 1 54 9',맨손:'M15 57 L11 35 Q10 29 17 28 L22 36 L20 18 Q21 11 26 16 L31 34 L31 13 Q35 9 38 16 L39 34 L43 19 Q49 17 49 24 L47 40 L54 34 Q61 33 60 40 L45 58 Z'};
export function opponentArt(s){return s.battle?.zone==='waterway'?'guard':s.battle?.zone==='pass'?'leader':'bandit';}
export const effectsDuration=(s,speed=1)=>Math.max(850,(s.battle?.effects?.length||0)*390+240)/speed;
export function battleStage(s,{speed=1,paused=false,replay=false}={}){
 const b=s.battle,events=b.effects||[],enemy=opponentArt(s),scene=s.battle?.zone==='waterway'?'spring':s.battle?.zone==='trail'?'courtyard':'bridge';
 const timeline=(side)=>events.map((e,i)=>{const type=e.actor===side&&['attack','skill','counter'].includes(e.kind)?'lunge':e.target===side&&['attack','skill','counter','burn'].includes(e.kind)&&e.amount>0?'hurt':e.target===side&&e.kind==='dodge'?'evade':null;return type?`${side}-${type} ${360/speed}ms ${i*390/speed}ms forwards`:null;}).filter(Boolean).join(',');
 const attackArt=(e,i)=>{const side=e.target==='player'?'player':'enemy',delay=i*390/speed;const damage=['attack','skill','counter','burn'].includes(e.kind),support=['guard','block','heal','recover','stun'].includes(e.kind);return `<div class="battle-effect ${side} kind-${e.kind}" data-effect="${e.kind}" style="--delay:${delay}ms;--duration:${380/speed}ms;--effect-color:${e.actor==='enemy'?'#e4a284':colors[e.element]}">${damage?`<span class="strike-fx ${e.kind==='skill'?'arcane':''}"></span>`:''}${support?'<span class="guard-shell"></span>':''}<span class="damage-float">${e.kind==='dodge'?'회피':e.kind==='guard'?'보호막 +'+e.amount:e.kind==='block'?'흡수 '+e.amount:e.kind==='heal'?'체력 +'+e.amount:e.kind==='recover'?'숨 +'+e.amount:e.kind==='stun'?'경직':e.kind==='move'?'접근':(e.critical?'치명 ':'')+'−'+e.amount}</span></div><div class="action-cue kind-${e.kind}" style="--delay:${delay}ms;--duration:${380/speed}ms"><small>${e.kind==='counter'?'COUNTER':e.kind==='block'?'BLOCK':e.kind==='guard'?'GUARD':e.kind==='dodge'?'EVADE':e.kind==='skill'?'SKILL':e.kind==='attack'?'ATTACK':e.kind==='heal'?'HEAL':e.kind==='recover'?'BREATH':'EFFECT'}</small><strong>${esc(e.label)}</strong></div>`;};
 return `<section class="duel-stage ${paused&&!replay?'paused':''} ${events.length?'has-action':''}" aria-label="${esc(s.name)}과 ${esc(b.enemy.name)}의 전투 장면" style="--element-color:${colors[s.element]};--stage-image:url('assets/${scene}.png')"><div class="duel-mist"></div><div class="duelist player ${b.outcome==='defeat'?'fallen':''}" style="animation:${timeline('player')||'none'}"><img src="assets/combat/apprentice.png" alt="자세를 잡고 상대를 바라보는 제자의 뒷모습" width="1024" height="1536"><span class="weapon-token" aria-label="${s.weapon}"><svg viewBox="0 0 70 70" aria-hidden="true"><path d="${weaponPaths[s.weapon]}"/></svg></span><span class="duelist-name">${esc(s.name)}<small>${s.weapon} · ${s.element}</small></span></div><div class="duelist enemy ${enemy} ${b.outcome==='victory'?'fallen':''}" style="animation:${timeline('enemy')||'none'}"><img src="assets/combat/${enemy}.png" alt="${esc(b.enemy.name)}의 전신 모습" width="1024" height="1536"><span class="duelist-name">${esc(b.enemy.name)}<small>${esc(b.enemy.weapon||'짧은 칼')}</small></span></div>${b.playerShield>0?`<div class="persistent-shield" aria-label="플레이어 보호막 ${b.playerShield}">보호막 ${b.playerShield}</div>`:''}${b.counter?'<div class="counter-ready">반격 대기</div>':''}${events.map(attackArt).join('')}${!events.length?'<p class="duel-ready">숨을 고르고, 상대를 마주한다.</p>':''}<div class="stage-caption"><span>${paused?'PAUSED':'AUTOMATIC BATTLE'}</span><span>${b.round}번째 공방</span></div></section>`;
}
